                CanonicalLineText(line = 5, text = "君子维有解，吉；有孚于小人。", smallImage = "君子有解，小人退也。"),
                CanonicalLineText(line = 6, text = "公用射隼，于高墉之上，获之，无不利。", smallImage = "公用射隼，以解悖也。"),
