        CanonicalHexagramText(
            kingWenOrder = 41,
            name = "损",
            judgment = "有孚，元吉。无咎，可贞，利有攸往。曷之用？二簋可用享。",
            tuan = "损，损下益上，其道上行。损而有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享；二簋应有时。损刚益柔有时，损益盈虚，与时偕行。",
            greatImage = "山下有泽，损；君子以惩忿窒欲。",
            lines = listOf(
                CanonicalLineText(line = 1, text = "已事遄往，无咎，酌损之。", smallImage = "已事遄往，尚合志也。"),
                CanonicalLineText(line = 2, text = "利贞，征凶，弗损益之。", smallImage = "九二利贞，中以为志也。"),
                CanonicalLineText(line = 3, text = "三人行，则损一人；一人行，则得其友。", smallImage = "一人行，三则疑也。"),
                CanonicalLineText(line = 4, text = "损其疾，使遄有喜，无咎。", smallImage = "损其疾，亦可喜也。"),
                CanonicalLineText(line = 5, text = "或益之，十朋之龟弗克违，元吉。", smallImage = "六五元吉，自上佑也。"),
                CanonicalLineText(line = 6, text = "弗损益之，无咎，贞吉，利有攸往，得臣无家。", smallImage = "弗损益之，大得志也。"),
