        CanonicalHexagramText(
            kingWenOrder = 42,
            name = "益",
            judgment = "利有攸往。利涉大川。",
            tuan = "益，损上益下，民说无疆，自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。",
            greatImage = "风雷，益；君子以见善则迁，有过则改。",
            lines = listOf(
                CanonicalLineText(line = 1, text = "利用为大作，元吉，无咎。", smallImage = "元吉无咎，下不厚事也。"),
                CanonicalLineText(line = 2, text = "或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。", smallImage = "或益之，自外来也。"),
                CanonicalLineText(line = 3, text = "益之用凶事，无咎。有孚中行，告公用圭。", smallImage = "益用凶事，固有之也。"),
                CanonicalLineText(line = 4, text = "中行，告公从。利用为依迁国。", smallImage = "告公从，以益志也。"),
                CanonicalLineText(line = 5, text = "有孚惠心，勿问元吉。有孚惠我德。", smallImage = "有孚惠心，勿问之矣。惠我德，大得志也。"),
                CanonicalLineText(line = 6, text = "莫益之，或击之，立心勿恒，凶。", smallImage = "莫益之，偏辞也。或击之，自外来也。"),
